<?php
declare(strict_types=1);
use Vendi\Database\Connection;use Vendi\Http\ApiGuard;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();ApiGuard::permission('customers.documents');ApiGuard::csrf();$b=(int)$u['business_id'];$customer=(int)($_POST['customer_id']??0);if(!$customer||empty($_FILES['file']['tmp_name']))throw new RuntimeException('Archivo requerido.');$f=$_FILES['file'];if((int)$f['size']>10*1024*1024)throw new RuntimeException('El archivo excede 10 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))throw new RuntimeException('Solo PDF, JPG, PNG o WEBP.');$db=Connection::get();$q=$db->prepare("SELECT id FROM customers WHERE id=? AND business_id=?");$q->execute([$customer,$b]);if(!$q->fetchColumn())throw new RuntimeException('Cliente inválido.');$dir=dirname(__DIR__,3).'/storage/customer_documents/'.$b.'/'.$customer;if(!is_dir($dir)&&!mkdir($dir,0750,true))throw new RuntimeException('No se pudo preparar almacenamiento.');$name=bin2hex(random_bytes(20)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('No se pudo guardar el archivo.');$i=$db->prepare("INSERT INTO customer_documents(business_id,customer_id,uploaded_by,original_name,stored_name,mime_type,file_size) VALUES(?,?,?,?,?,?,?)");$i->execute([$b,$customer,(int)$u['id'],basename((string)$f['name']),$name,$mime,(int)$f['size']]);echo json_encode(['ok'=>true,'document_id'=>(int)$db->lastInsertId()]);}catch(Throwable$e){http_response_code(400);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
